import { context } from "@opentelemetry/api";
import { RESERVED_METRIC_ATTRIBUTES } from "./reserved-attributes.js";
import { telemetryStoreFrom } from "./session-telemetry.js";
import { validateTelemetryAttributes } from "./telemetry-attributes.js";
/** Trace tags, metric tags, and log tags for the active turn. No-op outside one. */
export const telemetry = {
    setTraceAttributes(attributes) {
        const store = activeStore();
        if (store === undefined) {
            return;
        }
        write(store.span, attributes, undefined, (cleaned) => store.applySpan?.(cleaned));
    },
    setMetricAttributes(attributes) {
        const store = activeStore();
        if (store === undefined) {
            return;
        }
        write(store.metric, attributes, RESERVED_METRIC_ATTRIBUTES);
    },
    setLogAttributes(attributes) {
        const store = activeStore();
        if (store === undefined) {
            return;
        }
        write(store.log, attributes);
    },
};
function activeStore() {
    return telemetryStoreFrom(context.active());
}
function write(target, attributes, reserved, apply) {
    const cleaned = validateTelemetryAttributes(attributes, target, reserved);
    Object.assign(target, cleaned);
    apply?.(cleaned);
}
